@dataclass
class CalibrationArtifacts:
    theta_samples: np.ndarray
    x_samples: np.ndarray
    loss_history: List[float]
    x_mean: np.ndarray
    x_std: np.ndarray


class BaseCalibrator:
    def fit(
        self,
        model: HospitalFlowModel,
        train_states: List[List[Dict[str, Any]]],
        *,
        num_simulations: int,
        device: str,
    ) -> Tuple[np.ndarray, CalibrationArtifacts]:
        raise NotImplementedError


class NPEGaussianCalibrator(BaseCalibrator):
    """
    Torch-backed when available; deterministic fallback when torch isn't installed.
    """

    def __init__(
        self,
        seed: int,
        epochs: int = 200,
        batch_size: int = 64,
        lr: float = 1e-3,
        hidden_sizes: Sequence[int] = (256, 256),
    ) -> None:
        if epochs <= 0:
            raise ValueError("epochs must be positive.")
        if batch_size <= 0:
            raise ValueError("batch_size must be positive.")
        if lr <= 0:
            raise ValueError("lr must be positive.")
        self.seed = seed
        self.epochs = epochs
        self.batch_size = batch_size
        self.lr = lr
        self.hidden_sizes = tuple(int(h) for h in hidden_sizes)

    @staticmethod
    def _sample_prior(
        rng: np.random.Generator,
        n: int,
        theta_min: np.ndarray,
        theta_max: np.ndarray,
    ) -> np.ndarray:
        u = rng.random((n, theta_min.shape[0]))
        return theta_min + u * (theta_max - theta_min)

    @staticmethod
    def _make_observation_xo(train_states: List[List[Dict[str, Any]]]) -> np.ndarray:
        if not train_states:
            raise ValueError("train_states is empty.")
        observed_traj = train_states[0]
        obs_np = trajectories_to_numpy(observed_traj)
        return obs_np.reshape(-1).astype(np.float32)

    def fit(
        self,
        model: HospitalFlowModel,
        train_states: List[List[Dict[str, Any]]],
        *,
        num_simulations: int,
        device: str,
    ) -> Tuple[np.ndarray, CalibrationArtifacts]:
        if num_simulations <= 0:
            raise ValueError("num_simulations must be positive.")
        if not train_states or not train_states[0]:
            raise ValueError("train_states must contain at least one non-empty trajectory.")

        theta_min, theta_max = model.get_parameters_uniform_prior_min_max()
        theta_dim = int(theta_min.shape[0])

        xo = self._make_observation_xo(train_states)
        x_dim = int(xo.shape[0])

        init_state = train_states[0][0]
        horizon = len(train_states[0]) - 1
        if horizon < 0:
            raise ValueError("Observed trajectory horizon must be >= 0.")

        # Always generate samples (used for artifacts), even in fallback mode.
        theta_samples = self._sample_prior(model.rng, num_simulations, theta_min, theta_max).astype(np.float32)
        x_samples = np.zeros((num_simulations, x_dim), dtype=np.float32)

        for i in range(num_simulations):
            theta_i = theta_samples[i].astype(np.float64)
            model.set_parameters(theta_i)
            sim_traj = model.rollout(init_state=init_state, horizon=horizon)
            xi = trajectories_to_numpy(sim_traj).reshape(-1).astype(np.float32)
            if xi.shape[0] != x_dim:
                raise RuntimeError(
                    f"Simulator produced x_dim={xi.shape[0]} but expected {x_dim}. Check horizon alignment."
                )
            x_samples[i] = xi

        x_mean = x_samples.mean(axis=0)
        x_std = x_samples.std(axis=0)
        x_std = np.where(x_std < 1e-6, 1.0, x_std)

        if not TORCH_AVAILABLE:
            optimized_theta = 0.5 * (theta_min + theta_max)
            optimized_theta = np.asarray(np.clip(optimized_theta, theta_min, theta_max), dtype=np.float64)
            artifacts = CalibrationArtifacts(
                theta_samples=theta_samples.astype(np.float64),
                x_samples=x_samples.astype(np.float64),
                loss_history=[float("nan")],
                x_mean=x_mean.astype(np.float64),
                x_std=x_std.astype(np.float64),
            )
            return optimized_theta, artifacts

        if device == "cuda" and (not hasattr(torch, "cuda") or not torch.cuda.is_available()):  # type: ignore[union-attr]
            raise RuntimeError("CUDA requested but not available. Use --device cpu.")
        torch_device = torch.device(device)  # type: ignore[union-attr]

        x_samples_std = (x_samples - x_mean) / x_std
        xo_std = (xo - x_mean) / x_std

        theta_mean = theta_samples.mean(axis=0)
        theta_std = theta_samples.std(axis=0)
        theta_std = np.where(theta_std < 1e-6, 1.0, theta_std)
        theta_samples_std = (theta_samples - theta_mean) / theta_std

        X = torch.from_numpy(x_samples_std).to(torch_device)  # type: ignore[union-attr]
        Y = torch.from_numpy(theta_samples_std).to(torch_device)  # type: ignore[union-attr]

        class GaussianPosteriorNet(nn.Module):  # type: ignore[misc, valid-type]
            def __init__(self, x_dim_i: int, theta_dim_i: int, hidden_sizes_i: Sequence[int]) -> None:
                super().__init__()
                layers: List[nn.Module] = []
                prev = x_dim_i
                for h in hidden_sizes_i:
                    layers.append(nn.Linear(prev, int(h)))
                    layers.append(nn.ReLU())
                    prev = int(h)
                self.backbone = nn.Sequential(*layers)
                self.mean_head = nn.Linear(prev, theta_dim_i)
                self.log_std_head = nn.Linear(prev, theta_dim_i)

            def forward(self, x: "torch.Tensor") -> Tuple["torch.Tensor", "torch.Tensor"]:
                h = self.backbone(x)
                mean = self.mean_head(h)
                log_std = self.log_std_head(h).clamp(-5.0, 3.0)
                return mean, log_std

        net = GaussianPosteriorNet(
            x_dim_i=x_dim,
            theta_dim_i=theta_dim,
            hidden_sizes_i=self.hidden_sizes,
        ).to(torch_device)

        opt = optim.Adam(net.parameters(), lr=self.lr)  # type: ignore[union-attr]

        def nll_diag_gaussian(mean: "torch.Tensor", log_std: "torch.Tensor", y: "torch.Tensor") -> "torch.Tensor":
            var = torch.exp(2.0 * log_std)  # type: ignore[union-attr]
            nll = 0.5 * (math.log(2.0 * math.pi) + 2.0 * log_std + ((y - mean) ** 2) / var)
            return nll.sum(dim=1).mean()

        loss_history: List[float] = []
        n = num_simulations
        indices = np.arange(n)

        for _epoch in range(self.epochs):
            model.rng.shuffle(indices)
            epoch_losses: List[float] = []
            for start in range(0, n, self.batch_size):
                batch_idx = indices[start : start + self.batch_size]
                xb = X[batch_idx]
                yb = Y[batch_idx]

                mean_t, log_std_t = net(xb)
                loss = nll_diag_gaussian(mean_t, log_std_t, yb)

                opt.zero_grad(set_to_none=True)
                loss.backward()
                opt.step()

                epoch_losses.append(float(loss.detach().cpu().item()))
            loss_history.append(float(np.mean(epoch_losses)) if epoch_losses else float("nan"))

        with torch.no_grad():  # type: ignore[union-attr]
            xo_t = torch.from_numpy(xo_std.reshape(1, -1)).to(torch_device)  # type: ignore[union-attr]
            post_mean_std, _post_log_std = net(xo_t)
            post_mean_std = post_mean_std.squeeze(0).detach().cpu().numpy().astype(np.float64)

        optimized_theta_mean = (post_mean_std * theta_std.astype(np.float64)) + theta_mean.astype(np.float64)
        optimized_theta_mean = np.clip(optimized_theta_mean, theta_min, theta_max)
        optimized_theta = np.asarray(optimized_theta_mean, dtype=np.float64)

        artifacts = CalibrationArtifacts(
            theta_samples=theta_samples.astype(np.float64),
            x_samples=x_samples.astype(np.float64),
            loss_history=loss_history,
            x_mean=x_mean.astype(np.float64),
            x_std=x_std.astype(np.float64),
        )
        return optimized_theta, artifacts


